extern "C" void render(double *p,int n,unsigned char *im,int N,double side){
 double rx=p[0],ry=p[1],th=atan2(p[4]-p[1],p[3]-p[0]),w=0,d=0;
 double scale=N/side;
 for(int k=0;k<n;k++){
 double x=p[3*k],y=p[3*k+1],z=p[3*k+2];
 double zc=std::min(15.,std::max(0.,z))/10;
 w=.02*w+.98*(z>0?std::max(0.,11.87*zc-.3):0);
 d=.02*d+.98*(z>0?10.75*zc+1.38:0);
 double O=z>0?std::max(0.,10*(-.967*zc*zc+2.109994*zc-.036001727)):0;
 double vx=x-rx,vy=y-ry,L=hypot(vx,vy),o=std::min(O,L);
 if(L>(z>0?1.:.1))th=atan2(vy,vx);
 if(L>0){rx=x-vx*o/L;ry=y-vy*o/L;}
 if(w<.001||z<=0)continue;
 double ex=cos(th),ey=sin(th),nx=-ey,ny=ex;
 double bx[4]={rx+w/2*nx,rx-w/2*nx,rx-d*ex+w/2*nx,rx-d*ex-w/2*nx};
 double by[4]={ry+w/2*ny,ry-w/2*ny,ry-d*ey+w/2*ny,ry-d*ey-w/2*ny};
 int x0=std::max(0,(int)floor(*std::min_element(bx,bx+4)*scale)),x1=std::min(N-1,(int)ceil(*std::max_element(bx,bx+4)*scale));
 int y0=std::max(0,(int)floor(*std::min_element(by,by+4)*scale)),y1=std::min(N-1,(int)ceil(*std::max_element(by,by+4)*scale));
 for(int r=y0;r<=y1;r++)for(int c=x0;c<=x1;c++){
 double qx=(c+.5)/scale-rx,qy=(r+.5)/scale-ry;
 double s=-(qx*ex+qy*ey),t=qx*nx+qy*ny;
 if(s>=0&&s<=d*(1-4*t*t/w/w))im[r*N+c]=1;
 }
 }
}
