outside=cv2.distanceTransform((~T).astype('uint8'),cv2.DIST_L2,3)*SIDE/N
weights=1.5+np.minimum(outside,4)*.7
# xyz in original image pixels; z is mm
nodes=[
[[481,226,0],[510,245,7],[523,278,8],[514,355,6.5],[511,475,6.3],[511,600,6.6],[515,701,8],[507,753,11],[487,760,8],[447,725,5],[407,702,0]],
[[270,441,0],[300,451,4],[370,437,4.5],[425,430,6],[442,442,7],[418,498,7],[391,554,6],[349,612,5],[298,662,3],[245,698,0]],
[[659,316,0],[681,336,7],[679,367,6.5],[646,401,5],[601,439,3.5],[553,474,0]],
[[520,435,0],[553,483,4],[604,543,5.5],[661,597,7.5],[710,631,10],[762,641,6],[830,647,0]]]
nodes=[np.array(a,dtype=float) for a in nodes]
for a in nodes:a[:,:2]*=SIDE/1024

def sample(a,ds=.22):
    t=np.r_[0,np.cumsum(np.linalg.norm(np.diff(a[:,:2],axis=0),axis=1))]
    tt=np.linspace(0,t[-1],max(2,int(t[-1]/ds)))
    out=np.c_[CubicSpline(t,a[:,:2],axis=0,bc_type='natural')(tt),PchipInterpolator(t,a[:,2])(tt)]
    return np.ascontiguousarray(out)
def render(a):
    p=sample(a); im=np.zeros((N,N),np.uint8); lib.render(p,len(p),im,N,SIDE);return im

def metrics(M):
    M=M.astype(bool);inter=(M&T).sum();return dict(iou=inter/(M|T).sum(),recall=inter/T.sum(),stray=((outside>1)&M).sum()/T.sum())
def save(nodes,tag='fit'):
    np.savez(D/(tag+'.npz'),**{f's{i}':a for i,a in enumerate(nodes)})
    M=np.maximum.reduce([render(a) for a in nodes]).astype(bool)
    im=np.full((N,N,3),250,np.uint8);im[T]=[180,180,180];im[M&T]=[20,20,20];im[M&~T]=[40,40,240];im[T&~M]=[220,140,40]
    cv2.imwrite(str(D/(tag+'.png')),im)
    print(tag,metrics(M),flush=True)

def fit(nodes, rounds=4):
    masks=[render(a) for a in nodes]
    for r in range(rounds):
      for i,a in enumerate(nodes):
        others=np.maximum.reduce([m for j,m in enumerate(masks) if j!=i]).astype(bool)
        shape=a.shape; base=a.copy();bounds=[]
        for j,row in enumerate(a):
          bounds.extend([(row[0]-5,row[0]+5),(row[1]-5,row[1]+5),(0,0) if j in [0,len(a)-1] else (.3,15)])
        def fun(v):
          m=render(v.reshape(shape)).astype(bool)|others
          return ((T&~m).sum()+np.sum(weights[m&~T]))/T.sum()
        res=minimize(fun,a.ravel(),method='Powell',bounds=bounds,options={'maxiter':9,'xtol':.025,'ftol':.00008})
        nodes[i]=res.x.reshape(shape);masks[i]=render(nodes[i]); print(r,i,res.fun,res.nfev,flush=True)
        save(nodes)
    return nodes
if __name__=='__main__':
 import sys
 if (D/'fit.npz').exists():
  z=np.load(D/'fit.npz');nodes=[z[f's{i}'] for i in range(4)]
 save(nodes,'initial');fit(nodes,3)
